"""Summarize executed ambient checks and measured before/after timings."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
def read(name):return json.loads((ROOT/'tests'/name).read_text(encoding='utf-8'))

def main():
    checks=read('parallax-ambient-results.json');before=read('ambient-before-background-performance.json');after=read('ambient-performance-results.json')
    old_full=read('ambient-before-full-performance.json');new_full=read('ambient-after-full-performance.json');regression=read('review-results.json')
    assert all(value=='PASS' for value in checks['systems'].values()) and not checks['errors'],'ambient checks failed'
    assert not regression['summary']['failures'],'regression failed'
    fingerprints={r['execution']['sourceSha256'] for r in [checks,after,new_full,regression]};assert len(fingerprints)==1,'final source evidence mismatch'
    old={r['phase']:r for r in before['performance'] if not r['reduced']};normal=[r for r in after['performance'] if not r['reduced']];reduced=[r for r in after['performance'] if r['reduced']]
    delta=sum(r['meanMs']-old[r['phase']]['meanMs'] for r in normal)/10
    summary={'sourceSha256':next(iter(fingerprints)),'ambientChecks':len(checks['systems']),'regressionChecks':regression['summary']['passedSystems'],'visibilitySamples':len(checks['visibility']),'minDistinctBrightFraction':min(r['distinctFraction'] for r in checks['visibility']),'peakChangedPixelFraction':max(r['peakChangedFraction'] for r in checks['flashScreening']),'peakLargeLuminanceChangeFraction':max(r['peakBrightFraction'] for r in checks['flashScreening']),'observedMeanBackgroundDeltaMs':delta,'backgroundMeanMs':[min(r['meanMs'] for r in normal),max(r['meanMs'] for r in normal)],'reducedBackgroundMeanMs':[min(r['meanMs'] for r in reduced),max(r['meanMs'] for r in reduced)],'fullFrameBudgetFailuresBefore':sum(v!='PASS' for v in old_full['systems'].values()),'fullFrameBudgetFailuresAfter':sum(v!='PASS' for v in new_full['systems'].values()),'certifies60FPS':False}
    (ROOT/'tests/ambient-summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
    gallery=['<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>BYTE RUNNER — cenários vivos</title><style>body{margin:24px;background:#08151d;color:#e4eeef;font:16px system-ui}main{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}figure{margin:0}img{width:100%;image-rendering:pixelated}a{color:#8cdccc}h2{grid-column:1/-1}figcaption{padding:8px 0}@media(max-width:760px){main{grid-template-columns:1fr}}</style><h1>BYTE RUNNER — cenários vivos</h1><p>Capturas reais e estáticas. A série temporal usa a mesma câmera para comparar os pequenos movimentos sem reproduzir animação automaticamente.</p><main>']
    captions={'board':'Hardware: placa-mãe','ram':'Hardware: memória RAM','gpu':'Hardware: GPU e barramentos','power':'Hardware: alimentação final'}
    for shot in checks['snapshots']:
        file=Path(shot['file']).name;position=shot['position']
        label=captions.get(position,f'Fase {shot["phase"]:02}: '+('visibilidade do personagem' if position=='visibility' else 'quadro temporal '+position.removeprefix('motion-')))
        gallery.append(f'<figure><a href="{file}"><img loading="lazy" src="{file}" alt="{label}"></a><figcaption>{label}</figcaption></figure>')
    gallery.append('</main></html>');(ROOT/'tests/ambient-gallery.html').write_text(''.join(gallery),encoding='utf-8')
    lines=['# Cenários vivos — evidências e desempenho','','[Galeria de capturas](../tests/ambient-gallery.html) | [Registro da etapa](../PROGRESSO_MAPAS.md)','','## Verificação visual','',f'{summary["ambientChecks"]}/{summary["ambientChecks"]} verificações ambientais e {summary["regressionChecks"]}/{summary["regressionChecks"]} verificações de regressão aprovadas, sem erros de runtime.',f'Contraste verificado em {summary["visibilitySamples"]} posições reais de apoio, distribuídas pelas dez fases. No pior caso, {summary["minDistinctBrightFraction"]*100:.2f}% dos pixels claros detectados no robô ficaram pelo menos 40 níveis de luminância acima do cenário imediatamente anterior ao desenho do personagem. O teste usa luminância ponderada de 0 a 255.',f'Na triagem de quatro segundos por fase, com 24 intervalos de 1/6 s, o maior percentual de pixels que mudou foi {summary["peakChangedPixelFraction"]*100:.3f}%. Mudanças acima de 24 níveis de luminância atingiram no máximo {summary["peakLargeLuminanceChangeFraction"]*100:.3f}% do quadro. A triagem verifica a área e a intensidade nesta amostragem de quadros.','','## Parallax isolado — antes e depois','','Chrome headless, GPU desativada, Canvas 905 × 644; 24 quadros de aquecimento, 120 amostras por fase e modo, nove regiões de câmera, leitura síncrona de um pixel após desenhar. Os componentes continuam danificados, permitindo incluir seus sinais na medição. Valores em milissegundos.','','| Fase | Média antes | Média depois | p95 antes | p95 depois | Média reduzida depois |','| --- | ---: | ---: | ---: | ---: | ---: |']
    for r in normal:
        a=old[r['phase']];low=next(v for v in reduced if v['phase']==r['phase'])
        lines.append(f'| {r["phase"]} | {a["meanMs"]:.2f} | {r["meanMs"]:.2f} | {a["p95Ms"]:.2f} | {r["p95Ms"]:.2f} | {low["meanMs"]:.2f} |')
    lines+=['',f'Diferença média observada entre as dez fases: {delta:+.2f} ms por desenho do fundo. São execuções separadas, sujeitas à variação da máquina; a diferença não isola causalmente o custo de cada efeito. O modo reduzido elimina o novo passe decorativo. Hardware acrescenta 256 KiB de cache para quatro marcos regionais; as outras fases reutilizam seus atlas existentes. O limite total verificado é de 4 MiB por parallax.','','## Jogo completo — update + draw','','Mesmo navegador sem GPU; 24 quadros de aquecimento e 60 amostras por mapa, com nove posições de câmera. Este benchmark inclui combate e um mapa procedural de 24 salas. Os componentes são marcados como reparados por esse teste preexistente.','','| Mapa | Média antes | Média depois | p95 antes | p95 depois |','| --- | ---: | ---: | ---: | ---: |']
    for a,b in zip(old_full['performance'],new_full['performance']):lines.append(f'| {a["phase"]} | {a["meanMs"]:.2f} | {b["meanMs"]:.2f} | {a["p95Ms"]:.2f} | {b["p95Ms"]:.2f} |')
    lines+=['',f'O orçamento local de p95 ≤ 16,7 ms reprovou em {summary["fullFrameBudgetFailuresBefore"]} casos antes e {summary["fullFrameBudgetFailuresAfter"]} depois. Essa reprovação permanece registrada e não foi removida nem teve o limite relaxado. Os caches ficaram dentro do limite. Não há certificação de 60 FPS; uma otimização global e uma medição com GPU em hardware real continuam necessárias para esse objetivo.','','## Reprodução','','```powershell','python tests/run_review.py --ambient-only','python tests/run_review.py --ambient-performance','python tests/run_review.py --performance-only','python tests/run_review.py','python tests/report_ambient.py','```','','`--performance-only` retorna código 1 quando reprova o orçamento de frame; o JSON conserva todas as medidas. As medições anteriores estão em `tests/ambient-before-background-performance.json` e `tests/ambient-before-full-performance.json`. As posteriores estão em `tests/ambient-performance-results.json` e `tests/ambient-after-full-performance.json`. O resumo está em `tests/ambient-summary.json`.',f'Fontes finais: `{summary["sourceSha256"]}`.']
    (ROOT/'docs/parallax-life-review.md').write_text('\n'.join(lines)+'\n',encoding='utf-8');print(json.dumps(summary,indent=2))

if __name__=='__main__':main()
